window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0c1607e84465005c"]={"versions": [{"id": "FIG-0c1607e84465005c", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Textuelles Baum- und Abhängigkeitsdiagramm im Kontext des AUTOSAR Partial Network Cluster (PNC) Managements (System Template). Das Diagramm visualisiert die hierarchische Koordination von Partial Networking Clustern über mehrere Koordinatoren (PncCoordinator) und Kommunikationskanäle (Ch1, Ch2, etc.) hinweg sowie das Auftreten von Koordinationszyklen (PNC Coordination Tree with Cycle).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind hierarchisch geschachtelte Knotenstrukturen:</p>\n<ul class=\"fig-list\"><li>Koordinatoren: <code>PNC-Coor2</code>, <code>PNC-Coor3</code> sowie referenzierte Zielkoordinatoren.\n</li><li>Knoten und Kanäle: Netzwerk-Nodes (<code>Node1</code>, <code>Node2</code>, <code>Node3</code>, <code>Node4</code>) sowie Zuordnungen über Kanäle (<code>Ch1</code>, <code>Ch2</code>, <code>Ch3</code>).\n</li><li>Beziehungen: Pfade von Kanälen zu Endknoten oder untergeordneten Koordinatoren (z. B. <code>Ch2 -&gt; Node2</code>, <code>Ch2 -&gt; Node1</code>, <code>Ch1 -&gt; PNC-Coor2</code> bzw. <code>PNC-Coor...</code>).\n</li><li>Zyklus-Indikator: Rote Pfeilverbindungen, die Rückkopplungen bzw. zyklische Abhängigkeiten von untergeordneten Zweigen zurück auf übergeordnete Koordinatoren (<code>PNC-Coor2</code>, <code>PNC-Coor3</code>) anzeigen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aktivierungs- bzw. Freigabesignale für ein Partial Network Cluster (PNC) propagieren entlang des Koordinationsbaums über die definierten Kanäle zu den beteiligten Knoten und untergeordneten Koordinatoren. Durch die dargestellten zyklischen Pfade (über die roten Pfeile visualisiert) triggert ein Koordinator über seine Kanäle einen Folge-Koordinator, welcher wiederum über einen Pfad auf den Ursprungskoordinator zurückverweist. Dies führt zu einer zyklischen Selbsthaltung oder Deadlocks im PNC-Zustandsübergang, sofern keine Zykluserkennung oder Filterung im PNC-Gateway/Coordinator greift.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung von PNC-Koordinationsstrukturen im AUTOSAR System Template muss azyklisch erfolgen (Directed Acyclic Graph), um unendliche Weck-/Wachhaltezyklen im Netzwerkmanagement (ComM / Nm / PncGateway) zu verhindern. Das Diagramm dient als fehlerhaftes bzw. problematisches Negativbeispiel (Warnung), das zeigt, wie unvollständig entkoppelte oder zirkuläre Kanal-/Knoten-Zuweisungen zwischen mehreren PNC-Koordinatoren Zyklen erzeugen. System- und Netzwerkdesigner müssen Validierungsregeln anwenden, um solche zyklischen Abhängigkeiten in der System Description auszuschließen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2e7222d0481d09a0", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Textuelles Baum- und Abhängigkeitsdiagramm im Kontext des AUTOSAR Partial Network Cluster (PNC) Managements (System Template). Das Diagramm visualisiert die hierarchische Koordination von Partial Networking Clustern über mehrere Koordinatoren (PncCoordinator) und Kommunikationskanäle (Ch1, Ch2, etc.) hinweg sowie das Auftreten von Koordinationszyklen (PNC Coordination Tree with Cycle).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind hierarchisch geschachtelte Knotenstrukturen:</p>\n<ul class=\"fig-list\"><li>Koordinatoren: <code>PNC-Coor2</code>, <code>PNC-Coor3</code> sowie referenzierte Zielkoordinatoren.\n</li><li>Knoten und Kanäle: Netzwerk-Nodes (<code>Node1</code>, <code>Node2</code>, <code>Node3</code>, <code>Node4</code>) sowie Zuordnungen über Kanäle (<code>Ch1</code>, <code>Ch2</code>, <code>Ch3</code>).\n</li><li>Beziehungen: Pfade von Kanälen zu Endknoten oder untergeordneten Koordinatoren (z. B. <code>Ch2 -&gt; Node2</code>, <code>Ch2 -&gt; Node1</code>, <code>Ch1 -&gt; PNC-Coor2</code> bzw. <code>PNC-Coor...</code>).\n</li><li>Zyklus-Indikator: Rote Pfeilverbindungen, die Rückkopplungen bzw. zyklische Abhängigkeiten von untergeordneten Zweigen zurück auf übergeordnete Koordinatoren (<code>PNC-Coor2</code>, <code>PNC-Coor3</code>) anzeigen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aktivierungs- bzw. Freigabesignale für ein Partial Network Cluster (PNC) propagieren entlang des Koordinationsbaums über die definierten Kanäle zu den beteiligten Knoten und untergeordneten Koordinatoren. Durch die dargestellten zyklischen Pfade (über die roten Pfeile visualisiert) triggert ein Koordinator über seine Kanäle einen Folge-Koordinator, welcher wiederum über einen Pfad auf den Ursprungskoordinator zurückverweist. Dies führt zu einer zyklischen Selbsthaltung oder Deadlocks im PNC-Zustandsübergang, sofern keine Zykluserkennung oder Filterung im PNC-Gateway/Coordinator greift.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung von PNC-Koordinationsstrukturen im AUTOSAR System Template muss azyklisch erfolgen (Directed Acyclic Graph), um unendliche Weck-/Wachhaltezyklen im Netzwerkmanagement (ComM / Nm / PncGateway) zu verhindern. Das Diagramm dient als fehlerhaftes bzw. problematisches Negativbeispiel (Warnung), das zeigt, wie unvollständig entkoppelte oder zirkuläre Kanal-/Knoten-Zuweisungen zwischen mehreren PNC-Koordinatoren Zyklen erzeugen. System- und Netzwerkdesigner müssen Validierungsregeln anwenden, um solche zyklischen Abhängigkeiten in der System Description auszuschließen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0c1607e84465005c", "to": "FIG-2e7222d0481d09a0", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
